%%\ Tire Stud Detector (Image Preprocessing & Connected-Component Analysis)
clear; clc; close all;

if ~exist('screenshots', 'dir')
    mkdir('screenshots');
end

% Automatically handle .jpeg or .jpg filename for the studded tire image
if exist('studded_tire.jpeg', 'file')
    studdedFile = 'studded_tire.jpeg';
else
    studdedFile = 'studded_tire.jpg';
end
imageFiles = {studdedFile, 'summer_tire.jpg'};

% Tunable intensity & shape thresholds
darkThresh   = 120;   % Pixels darker than this belong to the rubber tire
brightThresh = 140;   % Bright metallic reflections inside the dark tire
minA         = 4;     % Minimum stud area (pixels)
maxA         = 150;   % Maximum stud area (pixels)
minCirc      = 0.60;  % Minimum circularity (1.0 = perfect circle)
maxEcc       = 0.85;  % Maximum eccentricity (0 = circle, 1 = line)

for i = 1:numel(imageFiles) %[output:group:6fcb2089]
    % ---------- 1) Read & resize ----------
    I = imread(imageFiles{i});
    I = imresize(I, 0.5); % Scale down for faster processing & consistent stud size

    % ---------- 2) Convert to grayscale ----------
    if size(I, 3) == 3
        Igray = rgb2gray(I);
    else
        Igray = I;
    end

    % ---------- 3) Create tire mask ----------
    % Tire rubber is dark against a bright/white background
    tireMask = Igray < darkThresh;
    tireMask = imfill(tireMask, 'holes');              % Fill inner rim & stud holes
    tireMask = bwareafilt(tireMask, 1);                % Keep only the largest dark object (tire)
    tireMask = imerode(tireMask, strel('disk', 5));    % Erode border to avoid edge glare

    % ---------- 4) Candidate studs ----------
    % Smooth slightly to suppress single-pixel noise, then threshold bright spots inside tire
    Iblur = imgaussfilt(Igray, 1.0);
    cand  = (Iblur > brightThresh) & tireMask;
    cand  = imfill(cand, 'holes');
    cand  = bwareaopen(cand, minA);                    % Remove tiny noise specks

    % ---------- 5) Connected components ----------
    CC    = bwconncomp(cand);
    stats = regionprops(CC, 'Area', 'Perimeter', 'Eccentricity');

    % ---------- 6) Filter candidates ----------
    studMask  = false(size(cand));
    studCount = 0;

    for k = 1:numel(stats)
        A = stats(k).Area;
        P = stats(k).Perimeter;
        E = stats(k).Eccentricity;

        if P > 0
            circ = 4 * pi * A / (P^2);
        else
            circ = 0;
        end

        % Keep only small, compact, round metallic studs
        if (A >= minA) && (A <= maxA) && (circ >= minCirc) && (E <= maxEcc)
            studMask(CC.PixelIdxList{k}) = true;
            studCount = studCount + 1;
        end
    end

    % ---------- 7) Decision rule ----------
    tireArea  = nnz(tireMask);
    density   = (studCount / max(tireArea, 1)) * 1e4; % Studs per 10,000 tire pixels
    isStudded = (studCount > 10);

    fprintf('Image: %-18s | Detected Studs: %3d | Density: %.2f / 10k px | Result: %s\n', ... %[output:4330f7f5] %[output:3cc74218]
        imageFiles{i}, studCount, density, ternary(isStudded, 'STUDDED TIRE', 'NON-STUDDED TIRE')); %[output:4330f7f5] %[output:3cc74218]

    % ---------- 8) Visualization ----------
    fig = figure('Name', sprintf('Results - %s', imageFiles{i})); %[output:009144ed] %[output:9c201c0c]
    tiledlayout(1, 3, 'TileSpacing', 'compact', 'Padding', 'compact'); %[output:009144ed] %[output:9c201c0c]

    nexttile;
    imshow(I);
    title(sprintf('Input: %s', imageFiles{i}), 'Interpreter', 'none');

    nexttile;
    imshow(cand);
    title('Candidate studs (binary)');

    nexttile;
    imshow(I); hold on;
    visboundaries(studMask, 'Color', 'r', 'LineWidth', 1.0);
    if isStudded
        title(sprintf('STUDDED TIRE (studs: %d)', studCount));
    else
        title(sprintf('NON-STUDDED TIRE (studs: %d)', studCount));
    end

    saveas(fig, fullfile('screenshots', sprintf('0%d_result_%s.png', i, erase(imageFiles{i}, {'.jpeg', '.jpg'}))));
end %[output:group:6fcb2089]

function out = ternary(cond, trueStr, falseStr)
    if cond
        out = trueStr;
    else
        out = falseStr;
    end
end

